select jsonb_build_object('funciones',(select jsonb_agg(pg_get_functiondef(oid)) from pg_proc where oid in ('private.conversion_episodios(timestamptz,timestamptz,date,boolean,uuid[],numeric)'::regprocedure,'private.metricas_distribucion_leads_core(date,date,timestamptz)'::regprocedure)), 'controles',jsonb_build_object('private.pares_autoridad',(select jsonb_agg(to_jsonb(t)) from private.pares_autoridad t),'crm.configuracion_reparto',(select jsonb_agg(to_jsonb(t)) from crm.configuracion_reparto t),'crm.conversion_pesos',(select jsonb_agg(to_jsonb(t)) from crm.conversion_pesos t),'crm.rentabilidad_hitos',(select jsonb_agg(to_jsonb(t)) from crm.rentabilidad_hitos t))) as extras;
